CREATE FUNCTION api.prompt_get(_key text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT vp.prompt_text
  FROM public.v_prompts vp
  WHERE vp.prompt_key = _key
    AND coalesce(vp.is_del,false) = false
  ORDER BY vp.created DESC
  LIMIT 1
$$;


