--
-- Name: trg_v__pcaches_ins(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_v__pcaches_ins() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_hash        text;
  v_existing_id uuid;
  v_new_id      uuid;
  x_meta_id uuid;
BEGIN

  v_hash := md5(NEW.pcache_prompt);
  
  SELECT t.meta_id
    INTO v_existing_id
    FROM public.v__pcaches t
   WHERE t.pcache_prompt_hash = v_hash
   LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    NEW.meta_id          := v_existing_id;
    NEW.pcache_prompt_hash := v_hash;
    RETURN NEW;
  END IF;

  -- вставка

  x_meta_id := public.create_record();
  
  INSERT INTO public.tb__pcaches (
    meta_id,
    pcache_prompt,
    pcache_prompt_hash,
    pcache_response,
    pcache_tokens_used
  ) VALUES (
    x_meta_id,
    NEW.pcache_prompt,
    v_hash,
    NEW.pcache_response,
    NEW.pcache_tokens_used
  )
  RETURNING meta_id INTO v_new_id;

  NEW.meta_id          := v_new_id;
  NEW.pcache_prompt_hash := v_hash;
  RETURN NEW;
END;
$$;


