    sk.sub_kind_code,
    sk.sub_kind_name,
    sk.sub_kind_value,
    char_length(sk.sub_kind_value) AS sub_kind_value_len,
    sk.sub_kind_type,
    sk.kind_meta_id,
    k.kind_code,
    k.kind_name,
    sk.sub_kind_default_value
   FROM (public.t_sub_kinds sk
     LEFT JOIN public.t_kinds k ON ((k.meta_id = sk.kind_meta_id)));


