лении.","tool_calls":[]},"logprobs":null,"finish_reason":"stop","stop_reason":null}],"usage":{"prompt_tokens":183,"total_tokens":544,"completion_tokens":361,"prompt_tokens_details":null},"prompt_logprobs":null,"kv_transfer_params":null}	544
